// CreateTableWithDBType creates the Tax_Posting_Setup table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *TaxPostingSetup) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, TaxPostingSetupTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetTaxPostingSetupPostgresTableSchema()
	} else {
		schema = GetTaxPostingSetupTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Tax_Posting_Setup table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *TaxPostingSetup) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, TaxPostingSetupTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (tax_bus_posting_group, tax_prod_posting_group)`,
		fmt.Sprintf("%s$Tax_Posting_Setup$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (tax_prod_posting_group, tax_bus_posting_group)`,
		fmt.Sprintf("%s$Tax_Posting_Setup$product", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index product: %w", err)
	}
	var keys []sift.Key
	for _, spec := range taxPostingSetupSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, TaxPostingSetupTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, TaxPostingSetupTableName, keys)
}

// taxPostingSetupSIFTSpecs are the table's keys with sum_index_fields
func taxPostingSetupSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *TaxPostingSetup) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, TaxPostingSetupTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range taxPostingSetupSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, TaxPostingSetupTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: TaxPostingSetupTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, TaxPostingSetupTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

